<template>
  <div class="mx-auto max-w-7xl space-y-5 p-4 pb-8">
    <div class="flex flex-col gap-3 md:flex-row md:items-center md:justify-between"><div class="flex items-center gap-3"><Button icon="pi pi-arrow-left" text rounded @click="router.visit('/crm/customers')"/><div><h1 class="text-xl font-semibold text-slate-900">Customer Details</h1><p class="text-sm text-slate-500">{{ customer?.lead_code || 'Loading customer…' }}</p></div></div><div v-if="customer" class="flex gap-2"><Button v-if="canCreateQuote" label="Create Quotation" icon="pi pi-file-edit" @click="router.visit(`/sales/wholesale-quotes/create?customer=${customer.id}`)"/><Tag :value="fmt(customer.stage)" :severity="stageSeverity(customer.stage)"/></div></div>
    <div v-if="loading" class="space-y-3"><Skeleton height="9rem"/><Skeleton height="20rem"/></div>
    <template v-else-if="customer">
      <div class="rounded-2xl bg-gradient-to-r from-slate-950 to-slate-800 p-6 text-white shadow-sm"><div class="flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div class="flex items-center gap-4"><div class="flex h-16 w-16 items-center justify-center rounded-2xl bg-orange-500 text-xl font-bold">{{ initials }}</div><div><p class="text-xs font-bold uppercase tracking-[.18em] text-orange-300">{{ fmt(customer.customer_type) }} customer</p><h2 class="mt-1 text-2xl font-bold">{{ customer.full_name }}</h2><p class="text-sm text-slate-300">{{ customer.company_name || 'Retail customer' }}</p></div></div><div class="grid grid-cols-3 gap-6 text-center"><div><p class="text-2xl font-bold">{{ summary.quotes }}</p><p class="text-xs text-slate-400">Quotes</p></div><div><p class="text-2xl font-bold">{{ summary.orders }}</p><p class="text-xs text-slate-400">Orders</p></div><div><p class="text-2xl font-bold text-orange-300">{{ compactMoney(summary.lifetime_value) }}</p><p class="text-xs text-slate-400">Lifetime value</p></div></div></div></div>
      <div class="grid gap-4 lg:grid-cols-3"><Card class="border shadow-sm lg:col-span-2"><template #title>Customer information</template><template #content><dl class="grid gap-5 text-sm md:grid-cols-2"><Info label="Contact person" :value="customer.full_name"/><Info label="Business" :value="customer.company_name||'Not applicable'"/><Info label="Email address" :value="customer.email||'Not provided'"/><Info label="Phone number" :value="customer.phone||'Not provided'"/><Info label="Address" :value="customer.address||'Not provided'"/><Info label="Source" :value="fmt(customer.source)"/><Info label="Assigned to" :value="customer.assignee?`${customer.assignee.fname} ${customer.assignee.lname}`:'Unassigned'"/><Info label="Branch" :value="customer.branch?.name||'Store-wide'"/></dl></template></Card><Card class="border shadow-sm"><template #title>CRM notes</template><template #content><p class="whitespace-pre-line text-sm leading-6 text-slate-600">{{ customer.notes||'No notes recorded.' }}</p><div class="mt-5 border-t pt-4"><p class="meta">Estimated opportunity</p><p class="mt-1 text-xl font-bold text-slate-900">{{ money(customer.estimated_value) }}</p></div></template></Card></div>
