      <div class="grid gap-4 lg:grid-cols-2"><Card class="border shadow-sm"><template #title>Sales transactions</template><template #content><DataTable :value="orders" dataKey="id" stripedRows responsiveLayout="scroll" class="text-xs"><template #empty><p class="py-8 text-center text-slate-500">No linked sales transactions.</p></template><Column field="order_number" header="Order"><template #body="{data}"><button class="font-semibold text-orange-600 hover:underline" @click="router.visit(`/sales/pos/orders/${data.id}`)">{{ data.order_number }}</button></template></Column><Column field="created_at" header="Date"><template #body="{data}">{{ date(data.created_at) }}</template></Column><Column field="total_amount" header="Total"><template #body="{data}">{{ money(data.total_amount) }}</template></Column><Column field="payment_status" header="Payment"><template #body="{data}"><Tag :value="fmt(data.payment_status||'pending')" :severity="data.payment_status==='paid'?'success':'warn'"/></template></Column></DataTable></template></Card><Card class="border shadow-sm"><template #title>Recent CRM activity</template><template #content><div v-if="customer.activities?.length" class="space-y-4"><div v-for="activity in customer.activities" :key="activity.id" class="flex gap-3 border-b border-slate-100 pb-3 last:border-0"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-orange-50 text-orange-600"><i :class="activityIcon(activity.activity_type)"/></span><div><p class="text-sm text-slate-700">{{ activity.description }}</p><p class="mt-1 text-[11px] text-slate-400">{{ dateTime(activity.activity_at||activity.created_at) }}</p></div></div></div><p v-else class="py-8 text-center text-sm text-slate-500">No activity recorded.</p></template></Card></div>
    </template>
    <Message v-else severity="error" :closable="false">Customer could not be found or does not belong to this store.</Message>
  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { router } from '@inertiajs/vue3'; import { useToast } from 'primevue/usetoast'; import { useAuthStore } from '@/stores/auth'; import crmService from '@/services/crm.service'; import Button from 'primevue/button'; import Card from 'primevue/card'; import Column from 'primevue/column'; import DataTable from 'primevue/datatable'; import Message from 'primevue/message'; import Skeleton from 'primevue/skeleton'; import Tag from 'primevue/tag'; import Info from './CustomerInfo.vue'
const id=Number(location.pathname.split('/').pop()),toast=useToast(),auth=useAuthStore(),loading=ref(true),customer=ref<any>(null),quotes=ref<any[]>([]),orders=ref<any[]>([]),summary=ref<any>({quotes:0,orders:0,lifetime_value:0}),canCreateQuote=computed(()=>auth.hasPermission('sales.orders.manage')),initials=computed(()=>String(customer.value?.full_name||'C').split(/\s+/).slice(0,2).map((x:string)=>x[0]).join('').toUpperCase())
const load=async()=>{loading.value=true;try{const r=await crmService.getCustomer(id),d=r.data;customer.value=d.customer;quotes.value=d.quotes||[];orders.value=d.orders||[];summary.value=d.summary||summary.value}catch(e:any){toast.add({severity:'error',summary:'Unable to load customer',detail:e.response?.data?.message||'Customer not found.',life:3000})}finally{loading.value=false}}
const fmt=(v:string)=>String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),money=(v:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(+v||0),compactMoney=(v:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',notation:'compact'}).format(+v||0),date=(v:any)=>v?new Intl.DateTimeFormat('en-PH',{dateStyle:'medium'}).format(new Date(v)):'—',dateTime=(v:any)=>v?new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—',stageSeverity=(v:string)=>['won','converted','accepted'].includes(v)?'success':['lost','declined'].includes(v)?'danger':['proposal','sent'].includes(v)?'warn':['qualified'].includes(v)?'info':'secondary',activityIcon=(v:string)=>v==='call'?'pi pi-phone':v==='email'?'pi pi-envelope':v==='meeting'?'pi pi-calendar':v==='stage_change'?'pi pi-sync':'pi pi-file-edit'; onMounted(load)
</script>
<style scoped>.meta{font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#64748b}</style>
